const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Hong Kong geometry
  const hongKong = ee.Geometry.Point([114.1694, 22.3193]).buffer(50000); // ~50 km buffer

  // Define time periods
  const period1Start = '2020-02-10';
  const period1End = '2020-02-25';
  const period2Start = '2020-04-20';
  const period2End = '2020-05-12';

  // Sentinel-5P NO2 collection
  const collection = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2');

  // Period 1: Feb 10-25, 2020
  const col1 = collection
    .filterDate(period1Start, period1End)
    .filterBounds(hongKong);

  const size1 = col1.size().getInfo();
  console.log(`Period 1 (Feb 10-25): ${size1} images`);

  if (size1 === 0) {
    console.log('No data for Period 1.');
    console.log('C1');
    return;
  }

  // Period 2: Apr 20-May 12, 2020
  const col2 = collection
    .filterDate(period2Start, period2End)
    .filterBounds(hongKong);

  const size2 = col2.size().getInfo();
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size2 === 0) {
    console.log('No data for Period 2.');
    console.log('C1');
    return;
  }

  // Function to calculate mean NO2 for a collection
  function getMeanNO2(imgCol, geom) {
    // Filter by quality flag and add band
    const filtered = imgCol.map(function(img) {
      const qa = img.select('qa_value');
      const no2 = img.select('tropospheric_NO2_column_number_density');
      return no2.updateMask(qa.gte(0.75)); // Good quality pixels only
    });

    const meanImg = filtered.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 3000,
      maxPixels: 1e9,
      bestEffort: true
    });

    const pixelCount = filtered.map(function(img) {
      return img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 3000,
        maxPixels: 1e9
      }).get('tropospheric_NO2_column_number_density');
    }).getInfo();

    return { stats: stats.getInfo(), pixels: pixelCount };
  }

  // Calculate mean NO2 for both periods
  const result1 = getMeanNO2(col1, hongKong);
  const result2 = getMeanNO2(col2, hongKong);

  const mean1 = result1.stats.tropospheric_NO2_column_number_density;
  const mean2 = result2.stats.tropospheric_NO2_column_number_density;

  console.log(`Period 1 mean NO2: ${mean1 !== null ? mean1.toFixed(4) : 'null'} molec/cm2`);
  console.log(`Period 2 mean NO2: ${mean2 !== null ? mean2.toFixed(4) : 'null'} molec/cm2`);
  console.log(`Valid pixels P1: ${result1.pixels[0] || 0}, P2: ${result2.pixels[0] || 0}`);

  // Validation
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < 0 || mean2 < 0 ||
      mean1 > 1e16 || mean2 > 1e16) {
    console.log('C3');
    return;
  }

  if (result1.pixels[0] === 0 || result2.pixels[0] === 0) {
    console.log('C2');
    return;
  }

  // Compare means
  const increase = mean2 > mean1;
  const change = ((mean2 - mean1) / mean1 * 100).toFixed(1);
  console.log(`Change: ${change}%`);

  if (increase) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
